INSERT INTO shared_banks (school_id, slug, title, description, payload, created_by) VALUES (v_school, 'contoh-bahasa-arab', 'Contoh Bahasa Arab', 'Mufradat, i''rab dasar, dan terjemah', '{"version": 1, "questions": [{"type": "pg", "content": {"text": "مَا مَعْنَى كَلِمَةِ «مَدْرَسَةٌ»؟", "options": ["Rumah", "Sekolah", "Masjid", "Pasar"]}, "answer_key": {"index": 1}, "points": 1, "rubric": null}, {"type": "pg", "content": {"text": "ذَهَبَ ... إِلَى الْمَدْرَسَةِ صَبَاحًا. Kata yang tepat untuk mengisi titik-titik adalah …", "options": ["أَحْمَدُ", "أَحْمَدَ", "أَحْمَدِ", "أَحْمَدٍ"]}, "answer_key": {"index": 0}, "points": 1, "rubric": null}, {"type": "pg", "content": {"text": "Bahasa Arab dari \"buku\" adalah …", "options": ["قَلَمٌ", "كِتَابٌ", "بَابٌ", "بَيْتٌ"]}, "answer_key": {"index": 1}, "points": 1, "rubric": null}, {"type": "benar_salah", "content": {"text": "كَلِمَةُ «مُعَلِّمٌ» مَعْنَاهَا guru.", "options": ["Benar", "Salah"]}, "answer_key": {"index": 0}, "points": 1, "rubric": null}, {"type": "pgk_kategori", "content": {"text": "Tentukan benar atau salah arti kata berikut.", "statements": ["بَيْتٌ = rumah", "شَمْسٌ = bulan", "مَاءٌ = air"], "cats": ["Benar", "Salah"]}, "answer_key": {"values": [0, 1, 0]}, "points": 3, "rubric": null}, {"type": "menjodohkan", "content": {"text": "Jodohkan kata dengan artinya.", "left": ["قَلَمٌ", "سَيَّارَةٌ", "تُفَّاحٌ"], "right": ["Apel", "Pena", "Mobil"]}, "answer_key": {"pairs": [[0, 1], [1, 2], [2, 0]]}, "points": 3, "rubric": null}, {"type": "isian", "content": {"text": "Arti kata «صَبَاحٌ» adalah …"}, "answer_key": {"accepted": ["pagi"]}, "points": 1, "rubric": null}, {"type": "uraian", "content": {"text": "تَرْجِمْ إِلَى اللُّغَةِ الْإِنْدُونِيسِيَّةِ: أَنَا طَالِبٌ فِي الْمَدْرَسَةِ."}, "answer_key": {"manual": true}, "points": 3, "rubric": "Saya (seorang) siswa di sekolah."}]}'::jsonb, v_admin) ON CONFLICT (slug) DO UPDATE SET payload = excluded.payload, title = excluded.title, description = excluded.description;
END $$;
